<script>
 import {formatDate} from '$lib/date.js';
 import {onMount} from 'svelte';import {locale} from '$lib/i18n.js';import {page} from '$app/stores';import {goto} from '$app/navigation';import {getProject,updateProject,deleteProject,listDevices,listSites,listDeployments,listLogs,attachProjectDevice,attachProjectSite,listProjectEnvironments,createProjectEnvironment,attachEnvironmentSite,listDatabaseServers,attachProjectDatabaseServer,detachProjectDevice,detachProjectSite,detachProjectDatabaseServer,getProjectRepository,connectProjectRepository,disconnectProjectRepository,listIntegrations,listIntegrationRepositories,listProjectRepositoryBranches,listProjectRepositoryPulls,getProjectRepositoryChecks,listProjectRepositorySites,connectProjectRepositorySite,disconnectProjectRepositorySite,listProjectDeploymentRuns,getProjectDeploymentRun,deployProjectSite,cancelProjectDeployment,redeployProjectDeployment,rollbackProjectDeployment,sendCommand,listProjectMembers,setProjectMemberRole,removeProjectMember,listAuditLogs} from '$lib/api.js';import {notify} from '$lib/stores.js';import Button from '$lib/components/Button.svelte';
 let project=null,devices=[],assigned=[],sites=[],sitesAvailable=[],environments=[],databaseServers=[],assignedDatabases=[],deployments=[],activity=[],projectMembers=[],activeTab='overview';let projectRepository=null,githubIntegrations=[],githubRepositories=[],selectedIntegration='',selectedRepository='',selectedBranch='',sourceBusy=false,sourceError='';let repositoryBranches=[],repositoryPulls=[],pullRequestState='open',repositoryTargets=[],deploymentRuns=[],selectedTarget='',targetBranch='',targetAutoDeploy=false,targetConsent=false,deployConsent=false,deploymentBranch='',deploymentCommit='',deploymentBusy=false,selectedCheckRef='',repositoryChecks=null,webhookSetup=null,runDetails=null;
 $: ru=$locale!=='en';let loading=true;let selectedDevice='';let selectedSite='';let appDevice='';let appEnvironment='';let appName='';let appPort='3000';let appRuntime='nodejs';let appBusy=false;let busyAppAction='';let busy=false;let newEnvironment='';let projectMemberUserId='';let projectMemberRole='developer';let selectedDatabase='';let editName='';let editDescription='';let editing=false;
remove counter loader async function load(){const [p,d,all,e,db,dep,logs,source,integrations]=await Promise.all([getProject($page.params.id),listDevices(),listSites(),listProjectEnvironments($page.params.id),listDatabaseServers(),listDeployments($page.params.id),listLogs(100,$page.params.id),getProjectRepository($page.params.id),listIntegrations()]);if(!p.ok){notify(p.error||'Проект не найден','error');goto('/projects');return}project=p.data.project;const memberResult=await listProjectMembers(project.id);projectMembers=memberResult.ok?(memberResult.data.members||[]):[];editName=project.name;editDescription=project.description||'';assigned=p.data.devices||[];sites=p.data.sites||[];if(d.ok)devices=d.data.devices||[];if(all.ok)sitesAvailable=all.data.sites||[];if(e.ok){environments=e.data.environments||[];if(!appEnvironment)appEnvironment=String((environments.find(x=>x.slug==='production')||environments[0])?.id||'')}if(db.ok)databaseServers=db.data.servers||[];assignedDatabases=p.data.database_servers||[];if(dep.ok)deployments=dep.data.deployments||[];if(logs.ok)activity=logs.data.logs||[];if(project.can_manage){const auditResult=await listAuditLogs(100,$page.params.id);if(auditResult.ok)activity=(auditResult.data.audit_logs||[]).concat(logs.ok?logs.data.logs||[]:[]).sort((a,b)=>new Date(b.created_at||0)-new Date(a.created_at||0)).slice(0,100)}if(source.ok)projectRepository=source.data.repository||null;if(integrations.ok)githubIntegrations=(integrations.data.integrations||[]).filter(x=>x.provider==='github_app');selectedIntegration=String(projectRepository?.integration_id||githubIntegrations[0]?.id||'');selectedBranch=projectRepository?.branch||'';deploymentBranch=selectedBranch;loading=false;await Promise.all([loadDeploymentRuns(),loadRepositoryTargets()]);if(selectedIntegration)await loadGitHubRepositories()}

 async function loadGitHubRepositories(){if(!selectedIntegration&&!projectRepository)return;sourceBusy=true;sourceError='';if(!projectRepository||Number(selectedIntegration)!==Number(projectRepository.integration_id)){const r=await listIntegrationRepositories(Number(selectedIntegration));if(r.ok){githubRepositories=r.data.repositories||[];if(projectRepository)selectedRepository=projectRepository.full_name;else if(!githubRepositories.some(x=>x.full_name===selectedRepository))selectedRepository=''}else{sourceError=r.error||'Could not load GitHub repositories';githubRepositories=[]}}if(projectRepository){const [b,p]=await Promise.all([listProjectRepositoryBranches(project.id),listProjectRepositoryPulls(project.id,pullRequestState)]);if(b.ok){repositoryBranches=b.data.branches||[];let next=b.data.next_page||0;while(next){const more=await listProjectRepositoryBranches(project.id,next);if(!more.ok)break;repositoryBranches=repositoryBranches.concat(more.data.branches||[]);next=more.data.next_page||0}}if(p.ok){repositoryPulls=p.data.pull_requests||[];let next=p.data.next_page||0;while(next){const more=await listProjectRepositoryPulls(project.id,pullRequestState,next);if(!more.ok)break;repositoryPulls=repositoryPulls.concat(more.data.pull_requests||[]);next=more.data.next_page||0}}else if(p.error)sourceError=p.error;}sourceBusy=false}
 async function connectRepository(){if(!selectedIntegration||!selectedRepository)return;sourceBusy=true;sourceError='';const r=await connectProjectRepository(project.id,selectedIntegration,selectedRepository,selectedBranch);sourceBusy=false;if(r.ok){projectRepository=r.data.repository;selectedBranch=projectRepository.branch;deploymentBranch=selectedBranch;notify(ru?'Репозиторий подключён':'Repository connected','success');await Promise.all([loadGitHubRepositories(),loadRepositoryTargets()])}else{sourceError=r.error||'Could not connect repository'}}

 async function loadRepositoryTargets(){if(!projectRepository)return;const r=await listProjectRepositorySites(project.id);if(r.ok)repositoryTargets=r.data.targets||[]}
 async function loadDeploymentRuns(){const r=await listProjectDeploymentRuns(project.id);if(r.ok)deploymentRuns=r.data.deployments||[]}
 async function connectTarget(){if(!selectedTarget)return;const [did,sid]=selectedTarget.split(':');sourceBusy=true;sourceError='';const r=await connectProjectRepositorySite(project.id,Number(did),sid,targetBranch||selectedBranch||projectRepository.branch,targetAutoDeploy,targetConsent);sourceBusy=false;if(r.ok){if(r.data.webhook_secret)webhookSetup={url:r.data.webhook_url||window.location.origin+r.data.webhook_path,secret:r.data.webhook_secret};notify(ru?'Сайт привязан к репозиторию':'Site linked to repository','success');selectedTarget='';await loadRepositoryTargets()}else sourceError=r.error||'Could not link site'}
 async function disconnectTarget(target){if(!confirm(ru?'Отключить сайт от GitHub Deploy?':'Disconnect site from GitHub Deploy?'))return;const r=await disconnectProjectRepositorySite(project.id,target.device_id,target.site_id);if(r.ok){notify(ru?'Связь отключена':'Target disconnected','success');await loadRepositoryTargets()}else sourceError=r.error||'Could not disconnect target'}
 async function loadProjectPulls(){if(!projectRepository)return;const p=await listProjectRepositoryPulls(project.id,pullRequestState);if(!p.ok){sourceError=p.error||'Could not load pull requests';return}repositoryPulls=p.data.pull_requests||[];let next=p.data.next_page||0;while(next){const more=await listProjectRepositoryPulls(project.id,pullRequestState,next);if(!more.ok)break;repositoryPulls=repositoryPulls.concat(more.data.pull_requests||[]);next=more.data.next_page||0}}
 async function loadChecks(ref){const value=(ref||selectedCheckRef||selectedBranch||projectRepository?.branch||'').trim();if(!value)return;selectedCheckRef=value;const r=await getProjectRepositoryChecks(project.id,value);if(r.ok)repositoryChecks=r.data;else sourceError=r.error||'Could not load checks'}
 async function selectDeploymentTarget(){const target=repositoryTargets.find(x=>String(x.device_id)+':'+x.site_id===selectedTarget);if(target?.branch)deploymentBranch=target.branch}
 async function startDeployment(){if(!selectedTarget||!deployConsent)return;const [did,sid]=selectedTarget.split(':');deploymentBusy=true;const r=await deployProjectSite(project.id,Number(did),sid,deploymentBranch||selectedBranch||projectRepository.branch,deploymentCommit.trim(),true);deploymentBusy=false;if(r.ok){notify(ru?'Развёртывание поставлено в очередь':'Deployment queued','success');await loadDeploymentRuns()}else notify(r.error||'Could not start deployment','error')}
 async function cancelDeploymentRun(run){const r=await cancelProjectDeployment(project.id,run.id);if(r.ok){notify(ru?'Отмена запрошена':'Cancellation requested','warning');await loadDeploymentRuns()}else notify(r.error||'Could not cancel deployment','error')}
 async function rollbackRun(run){if(!confirm(ru?'Откатить сайт к этому успешному релизу?':'Roll back the site to this successful release?'))return;const r=await rollbackProjectDeployment(project.id,run.id);if(r.ok){notify(ru?'Откат поставлен в очередь':'Rollback queued','success');await loadDeploymentRuns()}else notify(r.error||'Could not roll back','error')}
 async function redeployRun(run){const r=await redeployProjectDeployment(project.id,run.id);if(r.ok){notify(ru?'Повторный Deploy поставлен в очередь':'Redeploy queued','success');await loadDeploymentRuns()}else notify(r.error||'Could not redeploy','error')}
 async function openRunDetails(run){const r=await getProjectDeploymentRun(project.id,run.id);if(r.ok)runDetails=r.data.deployment;else notify(r.error||'Could not load deployment logs','error')}
 async function copyWebhookValue(value){try{await navigator.clipboard.writeText(value);notify(ru?'Скопировано':'Copied','success')}catch{notify(ru?'Не удалось скопировать':'Copy failed','error')}}

 async function disconnectRepository(){if(!confirm(ru?'Отключить репозиторий от проекта?':'Disconnect repository from this project?'))return;sourceBusy=true;const r=await disconnectProjectRepository(project.id);sourceBusy=false;if(r.ok){projectRepository=null;selectedRepository='';selectedBranch='';notify(ru?'Репозиторий отключён':'Repository disconnected','success')}else sourceError=r.error||'Could not disconnect repository'}

 onMount(load);
 $: projectApplications=sitesAvailable.filter(item=>sites.some(s=>String(s.device_id)===String(item.device_id)&&s.site_id===item.site.site_id));
 $: available=devices.filter(d=>d.workspace_owner_id===project?.owner_user_id&&!assigned.some(a=>a.id===d.id));
 $: availableDatabaseServers=databaseServers.filter(db=>db.workspace_owner_id===project?.owner_user_id&&!assignedDatabases.some(a=>a.id===db.id));
 $: availableSites=sitesAvailable.filter(item=>item.workspace_owner_id===project?.owner_user_id&&!sites.some(s=>s.device_id===item.device_id&&s.site_id===item.site.site_id));
 async function addDevice(){if(!selectedDevice)return;busy=true;const r=await attachProjectDevice(project.id,Number(selectedDevice));busy=false;if(r.ok){notify('Устройство добавлено','success');selectedDevice='';await load()}else notify(r.error||'Не удалось добавить устройство','error')}
 async function addSite(){if(!selectedSite)return;const [did,sid]=selectedSite.split(':');busy=true;const r=await attachProjectSite(project.id,Number(did),sid);busy=false;if(r.ok){notify('Сайт добавлен','success');selectedSite='';await load()}else notify(r.error||'Не удалось добавить сайт','error')}
 async function appAction(item,action){if(busyAppAction)return;busyAppAction=item.device_id+':'+item.site.site_id;const payload=action==='start_site'?{site_id:item.site.site_id,path:item.site.path,port:item.site.port,runtime:item.site.runtime}:{site_id:item.site.site_id};const result=await sendCommand(item.device_id,action,payload,project.id);busyAppAction='';if(!result.ok||!result.data?.ok){notify(result.error||result.data?.message||'Не удалось выполнить действие','error');return}notify(action==='start_site'?(ru?'Приложение запущено':'Application started'):(ru?'Приложение остановлено':'Application stopped'),'success');await load()}
 async function createApplication(){const id=appName.trim();const port=Number(appPort);if(!/^[A-Za-z0-9][A-Za-z0-9_-]{1,47}$/.test(id)){notify(ru?'ID приложения должен содержать 2–48 символов: латиница, цифры, _ или -':'Application ID must be 2–48 characters using letters, numbers, _ or -','error');return}if(!appDevice||!Number.isInteger(port)||port<1024||port>65535){notify(ru?'Выбери устройство и порт от 1024 до 65535':'Choose a device and a port from 1024 to 65535','error');return}appBusy=true;const result=await sendCommand(Number(appDevice),'create_site',{site_id:id,port,runtime:appRuntime},project.id);if(!result.ok||!result.data?.ok){appBusy=false;notify(result.error||result.data?.message||'Не удалось создать приложение','error');return}const attached=await attachProjectSite(project.id,Number(appDevice),id);if(!attached.ok){appBusy=false;notify(ru?'Приложение создано на устройстве, но не удалось привязать его к проекту':'Application created on the device but could not be linked to this project','error');await load();return}const envAttached=appEnvironment?await attachEnvironmentSite(project.id,Number(appEnvironment),Number(appDevice),id):{ok:true};appBusy=false;if(!envAttached.ok){notify(ru?'Приложение создано и добавлено в проект, но не удалось назначить окружение':'Application created and linked to the project, but environment assignment failed','error');await load();return}notify(ru?'Приложение создано и добавлено в окружение проекта':'Application created and assigned to the project environment','success');appName='';await load()}
 async function assignProjectMember(){if(!projectMemberUserId||busy)return;busy=true;const r=await setProjectMemberRole(project.id,Number(projectMemberUserId),projectMemberRole);busy=false;if(r.ok){notify(ru?'Роль участника проекта сохранена':'Project member role saved','success');projectMemberUserId='';await load()}else notify(r.error||'Не удалось назначить участника','error')}
 async function changeProjectMemberRole(member,role){if(busy||member.project_role==='owner')return;busy=true;const r=await setProjectMemberRole(project.id,member.user_id,role);busy=false;if(r.ok){notify(ru?'Роль участника обновлена':'Member role updated','success');await load()}else{notify(r.error||'Не удалось изменить роль','error');await load()}}
 async function unassignProjectMember(member){if(busy||member.project_role==='owner')return;if(!confirm((ru?'Убрать отдельную роль проекта для ':'Remove project role override for ')+member.username+'?'))return;busy=true;const r=await removeProjectMember(project.id,member.user_id);busy=false;if(r.ok){notify(ru?'Настройка роли удалена':'Project role override removed','success');await load()}else notify(r.error||'Не удалось убрать участника','error')}
 async function addDatabase(){if(!selectedDatabase)return;busy=true;const r=await attachProjectDatabaseServer(project.id,Number(selectedDatabase));busy=false;if(r.ok){notify('Database server добавлен в проект','success');selectedDatabase='';await load()}else notify(r.error||'Не удалось добавить сервер БД','error')}
 async function addEnvironment(){const name=newEnvironment.trim();if(name.length<2)return;busy=true;const r=await createProjectEnvironment(project.id,name);busy=false;if(r.ok){notify('Окружение создано','success');newEnvironment='';await load()}else notify(r.error||'Не удалось создать окружение','error')}
 async function saveProject(){const name=editName.trim();if(name.length<2||name.length>80){notify(ru?'Название проекта должно содержать 2–80 символов':'Project name must be 2–80 characters','error');return}busy=true;const r=await updateProject(project.id,name,editDescription);busy=false;if(r.ok){notify('Проект обновлён','success');editing=false;await load()}else notify(r.error||'Не удалось обновить проект','error')}
 async function removeProject(){if(!confirm('Удалить проект? Будут удалены только настройки группировки и привязки. Устройства, сайты, базы и их данные останутся без изменений.'))return;busy=true;const r=await deleteProject(project.id);busy=false;if(r.ok){notify('Проект удалён','success');goto('/projects')}else notify(r.error||'Не удалось удалить проект','error')}
 async function removeDevice(id){if(!confirm('Открепить устройство от проекта? Само устройство и его данные останутся без изменений.'))return;busy=true;const r=await detachProjectDevice(project.id,id);busy=false;if(r.ok){notify('Устройство откреплено','success');await load()}else notify(r.error||'Не удалось открепить устройство','error')}
 async function removeSite(deviceId,siteId){if(!confirm('Открепить сайт от проекта? Файлы и работа сайта не будут удалены.'))return;busy=true;const r=await detachProjectSite(project.id,deviceId,siteId);busy=false;if(r.ok){notify('Сайт откреплён','success');await load()}else notify(r.error||'Не удалось открепить сайт','error')}
 async function removeDatabase(id){if(!confirm('Открепить Database Server от проекта? Сервер и базы останутся без изменений.'))return;busy=true;const r=await detachProjectDatabaseServer(project.id,id);busy=false;if(r.ok){notify('Database Server detached','success');await load()}else notify(r.error||'Could not detach database server','error')}
</script>
{#if loading}<div class="empty">{ru?'Загрузка…':'Loading…'}</div>{:else if project}
<div class="page-header"><div><button class="back" on:click={()=>goto('/projects')}>← {ru?'Проекты':'Projects'}</button><h1 class="page-title">{project.name}</h1><p class="page-desc">{project.description||project.slug}</p></div>{#if project.can_manage}<div class="project-actions"><Button size="sm" on:click={()=>{activeTab='settings';editing=true}}>{ru?'Изменить':'Edit'}</Button><Button size="sm" variant="danger" disabled={busy} on:click={removeProject}>{ru?'Удалить проект':'Delete project'}</Button></div>{/if}</div>
<nav class="project-tabs"><button class:active={activeTab==='overview'} on:click={()=>activeTab='overview'}>{ru?'Обзор':'Overview'}</button><button class:active={activeTab==='environments'} on:click={()=>activeTab='environments'}>{ru?'Окружения':'Environments'}</button><button class:active={activeTab==='applications'} on:click={()=>activeTab='applications'}>{ru?'Приложения':'Applications'}</button><button class:active={activeTab==='deployments'} on:click={()=>activeTab='deployments'}>{ru?'Развёртывания':'Deployments'}</button><button class:active={activeTab==='activity'} on:click={()=>activeTab='activity'}>{ru?'Активность':'Activity'}</button><button class:active={activeTab==='source'} on:click={()=>activeTab='source'}>{ru?'Репозиторий':'Source repository'}</button><button class:active={activeTab==='settings'} on:click={()=>activeTab='settings'}>{ru?'Настройки':'Settings'}</button></nav>
{#if activeTab==='settings' && editing && project.can_manage}<section class="panel edit-panel"><label>{ru?'Название проекта':'Project name'}<input class="input" bind:value={editName} maxlength="80"/></label><label>{ru?'Описание':'Description'}<textarea class="input" bind:value={editDescription} maxlength="255" rows="2"></textarea></label><div class="add"><Button size="sm" on:click={()=>editing=false}>{ru?'Отмена':'Cancel'}</Button><Button size="sm" variant="primary" disabled={busy} on:click={saveProject}>{ru?'Сохранить':'Save'}</Button></div></section>{:else if activeTab==='settings'}<section class="panel"><h2>{ru?'Настройки проекта':'Project settings'}</h2><p>{ru?'Измени название и описание проекта или удали его.':'Update project name and description or delete the project.'}</p>{#if project.can_manage}<Button variant="primary" on:click={()=>editing=true}>{ru?'Редактировать проект':'Edit project'}</Button>{:else}<p>{ru?'У тебя нет прав на изменение проекта.':'You do not have permission to edit this project.'}</p>{/if}</section>{/if}
{#if activeTab==='settings'}<section class="panel"><div class="section-head"><div><h2>{ru?'Участники проекта':'Project members'}</h2><p>{ru?'Роли проекта могут переопределять роль рабочей области только в этом проекте.':'Project roles override workspace roles only inside this project.'}</p></div><span>{projectMembers.length}</span></div>
{#if project.can_manage}<div class="project-member-form"><label>{ru?'Участник рабочей области':'Workspace member'}<select class="input" bind:value={projectMemberUserId}><option value="">{ru?'Выбрать участника':'Select a member'}</option>{#each projectMembers.filter(x=>x.scope==='inherited'&&x.project_role!=='owner') as member}<option value={member.user_id}>{member.username} · {member.email} ({member.workspace_role})</option>{/each}</select></label><label>{ru?'Роль в проекте':'Project role'}<select class="input" bind:value={projectMemberRole}><option value="admin">Admin</option><option value="developer">Developer</option><option value="viewer">Viewer</option></select></label><Button variant="primary" disabled={busy||!projectMemberUserId} on:click={assignProjectMember}>{ru?'Назначить роль':'Assign role'}</Button></div>{/if}
{#if projectMembers.length}<div class="resource-list">{#each projectMembers as member}<div class="resource"><span class="resource-icon">{member.project_role==='owner'?'OW':member.project_role==='admin'?'AD':member.project_role==='viewer'?'VW':'DV'}</span><span><strong>{member.username||member.email}</strong><small>{member.email} · {member.workspace_role} {member.scope==='project'?'· '+(ru?'роль проекта':'project role'):(ru?'· наследуется':'· inherited')}</small></span>{#if project.can_manage&&member.scope==='project'&&member.project_role!=='owner'}<select class="input project-role-select" value={member.project_role} disabled={busy} on:change={(event)=>changeProjectMemberRole(member,event.currentTarget.value)}><option value="admin">Admin</option><option value="developer">Developer</option><option value="viewer">Viewer</option></select><Button size="sm" variant="danger" disabled={busy} on:click={()=>unassignProjectMember(member)}>{ru?'Сбросить':'Reset'}</Button>{:else}<span class="muted">{member.project_role}</span>{/if}</div>{/each}</div>{:else}<div class="empty compact">{ru?'Участники не найдены.':'No members found.'}</div>{/if}
<div class="security-summary"><strong>{ru?'Безопасность и доступ':'Security and access'}</strong><p>{ru?'Права проверяются сервером. Роли Admin, Developer и Viewer действуют только внутри этого проекта; если отдельная роль не назначена, наследуется роль рабочей области.':'Permissions are enforced server-side. Admin, Developer and Viewer roles apply only inside this project; without an override, the workspace role is inherited.'}</p><small>{ru?'Owner всегда сохраняет полный контроль. Viewer имеет доступ только для чтения.':'The Owner always retains full control. Viewer is read-only.'}</small></div></section>{/if}
{#if activeTab==='overview'}
<section class="overview-metrics"><article><small>{ru?'Устройства':'Devices'}</small><strong>{assigned.length}</strong></article><article><small>{ru?'Приложения':'Applications'}</small><strong>{sites.length}</strong></article><article><small>{ru?'Серверы БД':'Database servers'}</small><strong>{assignedDatabases.length}</strong></article><article><small>{ru?'Окружения':'Environments'}</small><strong>{environments.length}</strong></article><article><small>{ru?'Deployments':'Deployments'}</small><strong>{deploymentRuns.length}</strong></article></section>
<section class="panel"><div class="section-head"><div><h2>{ru?'Устройства':'Devices'}</h2><p>{ru?'Устройства, входящие в проект':'Devices assigned to this project'}</p></div>{#if project.can_manage}<div class="add"><select class="input" bind:value={selectedDevice}><option value="">{ru?'Выбрать устройство':'Select device'}</option>{#each available as d}<option value={d.id}>{d.hostname||d.device_id}</option>{/each}</select><Button variant="primary" disabled={!selectedDevice||busy} on:click={addDevice}>{ru?'Добавить':'Add'}</Button></div>{/if}</div>
{#if assigned.length}<div class="resource-list">{#each assigned as d}<div class="resource"><a class="resource-link" href={'/devices/'+d.id+'?project_id='+project.id}><span class="resource-icon">▣</span><span><strong>{d.hostname||d.device_id}</strong><small>{d.device_id}</small></span><span class="muted">{ru?'Открыть →':'Open →'}</span></a>{#if project.can_manage}<Button size="sm" variant="danger" disabled={busy} on:click={()=>removeDevice(d.id)}>{ru?'Открепить':'Detach'}</Button>{/if}</div>{/each}</div>{:else}<div class="empty compact">{ru?'В проект ещё не добавлены устройства.':'No devices have been added to this project.'}</div>{/if}</section>
<section class="panel"><div class="section-head"><div><h2>{ru?'Серверы баз данных':'Database Servers'}</h2><p>{ru?'Серверы баз данных, подключённые к проекту':'Database servers assigned to this project'}</p></div>{#if project.can_manage}<div class="add"><select class="input" bind:value={selectedDatabase}><option value="">{ru?'Выбрать сервер БД':'Select database server'}</option>{#each availableDatabaseServers as db}<option value={db.id}>{db.name} · {db.engine}</option>{/each}</select><Button variant="primary" disabled={!selectedDatabase||busy} on:click={addDatabase}>{ru?'Добавить':'Add'}</Button></div>{/if}</div>
{#if assignedDatabases.length}<div class="resource-list">{#each assignedDatabases as db}<div class="resource"><a class="resource-link" href={'/databases?project_id='+project.id}><span class="resource-icon">DB</span><span><strong>{db.name}</strong><small>{db.engine} · Device #{db.device_id} · {db.status}</small></span><span class="muted">{ru?'Открыть →':'Open →'}</span></a>{#if project.can_manage}<Button size="sm" variant="danger" disabled={busy} on:click={()=>removeDatabase(db.id)}>{ru?'Открепить':'Detach'}</Button>{/if}</div>{/each}</div>{:else}<div class="empty compact">{ru?'В проект ещё не добавлены Database Servers.':'No database servers have been added to this project.'}</div>{/if}</section>
<section class="panel"><div class="section-head"><div><h2>{ru?'Приложения проекта':'Project applications'}</h2><p>{ru?'Все сайты, подключённые к проекту':'All websites attached to this project'}</p></div><button class="text-action" on:click={()=>activeTab='applications'}>{ru?'Управлять →':'Manage →'}</button></div>
{#if projectApplications.length}<div class="resource-list">{#each projectApplications.slice(0,5) as item}<a class="resource-link overview-resource" href={'/sites/'+item.device_id+'/'+encodeURIComponent(item.site.site_id)+'?project_id='+project.id}><span class="resource-icon">◉</span><span><strong>{item.site.site_id}</strong><small>{item.device_name||'Android host'} · :{item.site.port} · {item.site.runtime}</small></span><span class="muted">{item.site.status}</span></a>{/each}</div>{:else}<div class="empty compact">{ru?'Приложений пока нет.':'No applications attached yet.'}</div>{/if}</section>
<section class="panel"><div class="section-head"><div><h2>{ru?'Окружения':'Environments'}</h2><p>{ru?'Изолированные конфигурации этого проекта':'Project-owned runtime configurations'}</p></div><button class="text-action" on:click={()=>activeTab='environments'}>{ru?'Управлять →':'Manage →'}</button></div>
<div class="environment-grid">{#each environments as env}<a class="environment-card" href={'/projects/'+project.id+'/environments/'+env.id}><div class="environment-top"><span class="environment-icon">▣</span>{#if env.is_protected}<span class="protected">{ru?'Защищено':'Protected'}</span>{:else}<span class="environment-state">{ru?'Окружение':'Environment'}</span>{/if}</div><strong>{env.name}</strong><small>{env.description||env.slug}</small><small>{env.application_count??0} apps · {env.database_server_count??0} DB servers · {env.database_count??0} databases</small><code>{env.slug}</code></a>{/each}</div></section>
{#if deploymentRuns.length}<section class="panel"><div class="section-head"><div><h2>{ru?'Последние Deployments':'Recent deployments'}</h2><p>{ru?'Недавние операции доставки проекта':'Latest project delivery runs'}</p></div><button class="text-action" on:click={()=>activeTab='deployments'}>{ru?'Все →':'View all →'}</button></div><div class="resource-list">{#each deploymentRuns.slice(0,4) as run}<div class="resource"><span class="resource-icon">⇧</span><span><strong>{run.site_id||run.target_name||'Deployment'}</strong><small>{run.branch||run.commit_sha||'—'} · {run.status}</small></span><span class="muted">{run.created_at?formatDate(run.created_at):'—'}</span></div>{/each}</div></section>{/if}
{/if}
{#if activeTab==='environments'}<section class="panel environments-panel"><div class="section-head"><div><h2>{ru?'Окружения проекта':'Project environments'}</h2><p>{ru?'У каждого проекта собственные независимые окружения':'Every project has its own independent environments'}</p></div>{#if project.can_manage}<div class="add"><input class="input" bind:value={newEnvironment} maxlength="64" placeholder={ru?'Название окружения':'Environment name'}/><Button variant="primary" disabled={busy||newEnvironment.trim().length<2} on:click={addEnvironment}>{ru?'Создать':'Create'}</Button></div>{/if}</div><div class="environment-grid">{#each environments as env}<a class="environment-card" href={'/projects/'+project.id+'/environments/'+env.id}><div class="environment-top"><span class="environment-icon">▣</span>{#if env.is_protected}<span class="protected">{ru?'Защищено':'Protected'}</span>{:else}<span class="environment-state">{ru?'Окружение':'Environment'}</span>{/if}</div><strong>{env.name}</strong><small>{env.description||env.slug}</small><code>{env.slug}</code><span class="environment-open">{ru?'Управлять ресурсами →':'Manage resources →'}</span></a>{/each}</div>{#if !environments.length}<div class="empty compact">{ru?'В этом проекте пока нет окружений.':'This project has no environments yet.'}</div>{/if}</section>{/if}
{#if activeTab==='applications'}<section class="panel"><div class="section-head"><div><h2>{ru?'Приложения проекта':'Project applications'}</h2><p>{ru?'Создавай сайты на устройствах проекта и управляй ими здесь':'Create websites on project devices and manage them here'}</p></div></div>{#if project.can_develop}<div class="application-create"><label>{ru?'Устройство':'Device'}<select class="input" bind:value={appDevice}><option value="">{ru?'Выбрать устройство':'Select device'}</option>{#each assigned as d}<option value={d.id}>{d.hostname||d.device_id}</option>{/each}</select></label><label>{ru?'Окружение':'Environment'}<select class="input" bind:value={appEnvironment}><option value="">{ru?'Без окружения':'No environment'}</option>{#each environments as env}<option value={env.id}>{env.name}</option>{/each}</select></label><label>{ru?'ID приложения':'Application ID'}<input class="input" bind:value={appName} maxlength="48" placeholder="my-website"/></label><label>{ru?'Порт':'Port'}<input class="input" type="number" min="1024" max="65535" bind:value={appPort}/></label><label>{ru?'Среда выполнения':'Runtime'}<select class="input" bind:value={appRuntime}><option value="nodejs">Node.js</option><option value="php">PHP</option><option value="static">Static</option><option value="go">Go</option><option value="custom">Custom</option></select></label><Button variant="primary" disabled={appBusy||!appDevice||!appName.trim()} loading={appBusy} on:click={createApplication}>{ru?'Создать приложение':'Create application'}</Button><small>{ru?'Создание выполняется на выбранном Agent. Устройство должно быть онлайн.':'Creation runs on the selected Agent. The device must be online.'}</small></div>{/if}
<section class="panel"><div class="section-head"><div><h2>{ru?'Сайты':'Websites'}</h2><p>{ru?'Сайты, сгруппированные в проекте':'Websites grouped in this project'}</p></div>{#if project.can_manage}<div class="add"><select class="input" bind:value={selectedSite}><option value="">{ru?'Выбрать сайт':'Select website'}</option>{#each availableSites as item}<option value={item.device_id+':'+item.site.site_id}>{item.device_name||'Android host'} / {item.site.site_id}</option>{/each}</select><Button variant="primary" disabled={!selectedSite||busy} on:click={addSite}>{ru?'Добавить':'Add'}</Button></div>{/if}</div>
{#if projectApplications.length}<div class="resource-list">{#each projectApplications as item}<div class="resource"><a class="resource-link" href={'/sites/'+item.device_id+'/'+encodeURIComponent(item.site.site_id)+'?project_id='+project.id}><span class="resource-icon">◉</span><span><strong>{item.site.site_id}</strong><small>{item.device_name||'Android host'} · :{item.site.port} · {item.site.runtime} · {item.site.status}</small></span><span class="muted">{ru?'Открыть →':'Open →'}</span></a>{#if project.can_develop}{#if item.site.status==='running'}<Button size="sm" disabled={!!busyAppAction} on:click={()=>appAction(item,'stop_site')}>{ru?'Остановить':'Stop'}</Button>{:else}<Button size="sm" variant="primary" disabled={!!busyAppAction} loading={busyAppAction===item.device_id+':'+item.site.site_id} on:click={()=>appAction(item,'start_site')}>{ru?'Запустить':'Start'}</Button>{/if}{/if}{#if project.can_manage}<Button size="sm" variant="danger" disabled={busy} on:click={()=>removeSite(item.device_id,item.site.site_id)}>{ru?'Открепить':'Detach'}</Button>{/if}</div>{/each}</div>{:else}<div class="empty compact">{ru?'Сайты пока не добавлены.':'No websites have been added yet.'}</div>{/if}</section></section>
{/if}
{#if activeTab==='deployments'}
<section class="panel">
 <div class="section-head"><div><h2>{ru?'Новые развёртывания':'New deployment'}</h2><p>{ru?'Запуск Git Deploy на выбранном сайте проекта':'Run a Git deployment on a project site'}</p></div></div>
 {#if projectRepository && repositoryTargets.length && project.can_manage}
 <div class="source-form">
  <label>{ru?'Сайт / устройство':'Site / device'}<select class="input" bind:value={selectedTarget} on:change={selectDeploymentTarget}><option value="">{ru?'Выбрать цель':'Select target'}</option>{#each repositoryTargets as target}<option value={target.device_id+':'+target.site_id}>{target.device_name} / {target.site_id}</option>{/each}</select></label>
  <label>{ru?'Ветка':'Branch'}<select class="input" bind:value={deploymentBranch}><option value={projectRepository.branch}>{projectRepository.branch}</option>{#each repositoryBranches as branch}<option value={branch.name}>{branch.name}{branch.protected?' · protected':''}</option>{/each}</select></label>
  <label>{ru?'Commit SHA (необязательно)':'Commit SHA (optional)'}<input class="input" bind:value={deploymentCommit} maxlength="64" placeholder={ru?'Последний commit выбранной ветки':'Latest commit on selected branch'}/></label>
  <label class="consent-inline"><input type="checkbox" bind:checked={deployConsent}/>{ru?'Я разрешаю клонирование, сборку и выполнение кода репозитория на выбранном Android-устройстве.':'I authorize cloning, building and executing repository code on the selected Android device.'}</label>
  <div class="source-actions"><Button size="sm" variant="primary" disabled={!selectedTarget||!deployConsent||deploymentBusy} loading={deploymentBusy} on:click={startDeployment}>{ru?'Запустить Deploy':'Start Deploy'}</Button><Button size="sm" on:click={loadDeploymentRuns}>{ru?'Обновить историю':'Refresh history'}</Button></div>
 </div>
 {:else if !projectRepository}
 <div class="empty compact">{ru?'Сначала подключи GitHub-репозиторий во вкладке «Репозиторий».':'Connect a GitHub repository in the Source Repository tab first.'}</div>
 {:else}
 <div class="empty compact">{ru?'Сначала привяжи сайт к репозиторию во вкладке «Репозиторий».':'Link a project site to the repository in the Source Repository tab first.'}</div>
 {/if}
</section>
<section class="panel">
 <div class="section-head"><div><h2>{ru?'История Deploy':'Deployment history'}</h2><p>{ru?'Состояния Agent, прогресс, сообщения и действия':'Agent states, progress, messages and actions'}</p></div><span>{deploymentRuns.length}</span></div>
 {#if deploymentRuns.length}
 <div class="resource-list">{#each deploymentRuns as run}
  <article class="deployment-row">
   <div class="deployment-row-main"><div class="deployment-row-title"><strong>{run.site_id}</strong><span class:state-success={run.status==='succeeded'} class:state-failed={run.status==='failed'} class:state-running={!['succeeded','failed','cancelled'].includes(run.status)}>{run.status}</span><small>{run.source} · {run.branch||'—'} · {run.created_at?formatDate(run.created_at):'—'}</small></div>
    {#if run.commit_sha}<code>{run.commit_sha}</code>{/if}<small>{run.message||'—'}</small>
    {#if !['succeeded','failed','cancelled'].includes(run.status)}<div class="deployment-progress"><div style={'width:'+Math.max(0,Math.min(100,Number(run.progress||0)))+'%'}></div></div>{/if}
   </div>
   <div class="deployment-row-actions"><Button size="sm" on:click={()=>openRunDetails(run)}>{ru?'Логи':'Logs'}</Button>{#if !['succeeded','failed','cancelled'].includes(run.status)}<Button size="sm" variant="danger" disabled={!run.agent_job_id} on:click={()=>cancelDeploymentRun(run)}>{ru?'Отменить':'Cancel'}</Button>{:else}<Button size="sm" on:click={()=>redeployRun(run)}>{ru?'Повторить':'Redeploy'}</Button>{#if run.status==='succeeded'}<Button size="sm" on:click={()=>rollbackRun(run)}>{ru?'Откатить':'Rollback'}</Button>{/if}{/if}</div>
  </article>
 {/each}</div>
 {:else}<div class="empty compact">{ru?'Развёртываний пока нет.':'No deployments yet.'}</div>{/if}
 {#if runDetails}<div class="deployment-log-panel"><div class="section-head"><div><h3>{ru?'Логи развёртывания':'Deployment logs'} #{runDetails.id}</h3><p>{runDetails.site_id} · {runDetails.status}</p></div><Button size="sm" on:click={()=>runDetails=null}>{ru?'Закрыть':'Close'}</Button></div><pre>{runDetails.output||runDetails.message||'No output recorded yet.'}</pre></div>{/if}
</section>{/if}
{#if activeTab==='activity'}<section class="panel"><div class="section-head"><div><h2>{ru?'Активность проекта':'Project activity'}</h2><p>{ru?'События, связанные с ресурсами проекта':'Events related to this project resources'}</p></div><span>{activity.length}</span></div>{#if activity.length}<div class="resource-list">{#each activity as item}<div class="resource"><span class="resource-icon">⌁</span><span><strong>{item.action?.replaceAll('_',' ')||'Event'}</strong><small>{item.target_type?item.target_type+' · '+item.target_id:(item.device||'Control Plane')} · {item.outcome||'—'}</small></span><span class="muted">{item.created_at?formatDate(item.created_at):'—'}</span></div>{/each}</div>{:else}<div class="empty compact">{ru?'Событий пока нет.':'No activity yet.'}</div>{/if}</section>{/if}
{#if activeTab==='source'}
<section class="panel">
 <div class="section-head"><div><h2>Source Repository</h2><p>{ru?'GitHub App, ветки, Pull Requests и сайты проекта':'GitHub App, branches, pull requests and project sites'}</p></div><span class:connected={!!projectRepository} class="coming-soon">{projectRepository?(ru?'Подключён':'Connected'):(ru?'Не подключён':'Not connected')}</span></div>
 {#if projectRepository}
 <div class="source-empty"><span class="resource-icon">GH</span><div><strong>{projectRepository.full_name}</strong><small>{projectRepository.private?(ru?'Приватный репозиторий':'Private repository'):(ru?'Публичный репозиторий':'Public repository')} · {ru?'Default branch':'Default branch'}: <code>{projectRepository.default_branch}</code></small><small>{ru?'Последний commit':'Latest commit'}: <code>{projectRepository.last_commit_sha||'—'}</code></small><a href={projectRepository.web_url} target="_blank" rel="noreferrer">{ru?'Открыть на GitHub':'Open on GitHub'} ↗</a></div></div>
 {#if project.can_manage}
 <div class="source-form">
  <label>{ru?'Ветка по умолчанию для новых целей':'Default branch for new targets'}<select class="input" bind:value={selectedBranch}><option value={projectRepository.branch}>{projectRepository.branch}</option>{#each repositoryBranches as branch}<option value={branch.name}>{branch.name}{branch.protected?' · protected':''}</option>{/each}</select></label>
  <div class="source-actions"><Button size="sm" variant="primary" disabled={sourceBusy||!selectedBranch} on:click={connectRepository}>{ru?'Сохранить ветку':'Save branch'}</Button><Button size="sm" variant="danger" disabled={sourceBusy} on:click={disconnectRepository}>{ru?'Отключить репозиторий':'Disconnect repository'}</Button><Button size="sm" disabled={sourceBusy} on:click={loadGitHubRepositories}>{ru?'Обновить GitHub':'Refresh GitHub'}</Button></div>
 </div>
 {:else}<p class="muted">{ru?'Нет прав на изменение репозитория проекта.':'You do not have permission to change this project repository.'}</p>{/if}
 <div class="source-subsection">
  <div class="section-head"><div><h3>{ru?'Pull Requests':'Pull Requests'}</h3><p>{ru?'Запросы на слияние из подключённого репозитория':'Pull requests from the connected repository'}</p></div><select class="input pr-state-select" bind:value={pullRequestState} on:change={loadProjectPulls}><option value="open">{ru?'Открытые':'Open'}</option><option value="closed">{ru?'Закрытые':'Closed'}</option><option value="all">{ru?'Все':'All'}</option></select><span>{repositoryPulls.length}</span></div>
  {#if repositoryPulls.length}<div class="resource-list">{#each repositoryPulls as pr}<div class="pr-row"><a class="pr-link" href={pr.url} target="_blank" rel="noreferrer"><span class="pr-number">#{pr.number}</span><span><strong>{pr.title}</strong><small>{pr.head_branch} → {pr.base_branch} · {pr.author}{pr.draft?' · Draft':''}</small></span><span class="muted">{pr.state} ↗</span></a><Button size="sm" on:click={()=>loadChecks(pr.head_sha)}>{ru?'Checks':'Checks'}</Button></div>{/each}</div>{:else}<p class="muted">{ru?'PR не найдены или GitHub App не имеет Pull requests: Read.':'No pull requests found, or the GitHub App needs Pull requests: Read permission.'}</p>{/if}
 </div>
 <div class="source-subsection">
  <div class="section-head"><div><h3>{ru?'Checks / CI':'Checks / CI'}</h3><p>{ru?'Статусы проверок выбранной ветки или commit':'Check statuses for a branch or commit'}</p></div></div>
  <div class="source-actions"><input class="input" bind:value={selectedCheckRef} placeholder={selectedBranch||projectRepository.branch}/><Button size="sm" on:click={()=>loadChecks(selectedCheckRef||selectedBranch)}>{ru?'Проверить':'Load checks'}</Button></div>
  {#if repositoryChecks}
   <p class="muted">{ru?'Commit status':'Commit status'}: <strong>{repositoryChecks.commit_status||'—'}</strong> · {ru?'Checks':'Checks'}: {repositoryChecks.check_total}</p>
   {#if repositoryChecks.check_runs?.length}<div class="resource-list">{#each repositoryChecks.check_runs as check}<div class="check-row"><span><strong>{check.name}</strong><small>{check.status} · {check.conclusion||'pending'}</small></span>{#if check.url}<a href={check.url} target="_blank" rel="noreferrer">↗</a>{/if}</div>{/each}</div>{/if}
   {#if repositoryChecks.statuses?.length}<div class="resource-list">{#each repositoryChecks.statuses as check}<div class="check-row"><span><strong>{check.context}</strong><small>{check.state} · {check.description}</small></span>{#if check.url}<a href={check.url} target="_blank" rel="noreferrer">↗</a>{/if}</div>{/each}</div>{/if}
  {/if}
 </div>
 <div class="source-subsection">
  <div class="section-head"><div><h3>{ru?'Привязка к сайтам':'Site deployment targets'}</h3><p>{ru?'Выбери конкретный сайт и устройство для этого репозитория':'Choose the exact site and device that will receive this repository'}</p></div><span>{repositoryTargets.length}</span></div>
  {#if project.can_manage}
  <div class="source-form">
   <label>{ru?'Сайт проекта':'Project site'}<select class="input" bind:value={selectedTarget}><option value="">{ru?'Выбрать сайт':'Select site'}</option>{#each sites as site}<option value={site.device_id+':'+site.site_id}>{site.device_name||'Android device'} / {site.site_id}</option>{/each}</select></label>
   <label>{ru?'Ветка для этого сайта':'Branch for this site'}<select class="input" bind:value={targetBranch}><option value={projectRepository.branch}>{projectRepository.branch}</option>{#each repositoryBranches as branch}<option value={branch.name}>{branch.name}</option>{/each}</select></label>
   <label class="consent-inline"><input type="checkbox" bind:checked={targetAutoDeploy}/>{ru?'Автоматически развёртывать при push в выбранную ветку':'Automatically deploy pushes to the selected branch'}</label>
   {#if targetAutoDeploy}<label class="consent-inline"><input type="checkbox" bind:checked={targetConsent}/>{ru?'Я разрешаю автоматически выполнять код этого репозитория на выбранном устройстве.':'I authorize automatic execution of this repository code on the selected device.'}</label>{/if}
   <div class="source-actions"><Button size="sm" variant="primary" disabled={!selectedTarget||sourceBusy||(targetAutoDeploy&&!targetConsent)} on:click={connectTarget}>{ru?'Привязать сайт':'Link site'}</Button><Button size="sm" on:click={loadRepositoryTargets}>{ru?'Обновить':'Refresh'}</Button></div>
  </div>
  {#if repositoryTargets.length}<div class="resource-list">{#each repositoryTargets as target}<div class="target-row"><span><strong>{target.device_name} / {target.site_id}</strong><small>{ru?'Ветка':'Branch'}: {target.branch} · {target.auto_deploy_enabled?(ru?'Auto Deploy включён':'Auto Deploy enabled'):(ru?'Ручной Deploy':'Manual deploy')}</small></span><Button size="sm" variant="danger" on:click={()=>disconnectTarget(target)}>{ru?'Отключить':'Disconnect'}</Button></div>{/each}</div>{:else}<p class="muted">{ru?'Сайты ещё не привязаны. Добавь сайт в проект на вкладке «Обзор».':'No sites linked yet. Add a site to the project on the Overview tab first.'}</p>{/if}
  {:else}<p class="muted">{ru?'Нет прав на изменение целей развёртывания.':'You do not have permission to manage deployment targets.'}</p>{/if}
 </div>
 {#if webhookSetup}
 <div class="webhook-secret"><strong>{ru?'Webhook создан. Добавь его в GitHub: Settings → Webhooks → Add webhook':'Webhook generated. Add it in GitHub: Settings → Webhooks → Add webhook'}</strong><small>Payload URL</small><code>{webhookSetup.url}</code><Button size="sm" on:click={()=>copyWebhookValue(webhookSetup.url)}>{ru?'Скопировать URL':'Copy URL'}</Button><small>Content type: application/json · Event: Just the push event</small><small>Secret</small><code>{webhookSetup.secret}</code><Button size="sm" on:click={()=>copyWebhookValue(webhookSetup.secret)}>{ru?'Скопировать Secret':'Copy secret'}</Button><small>{ru?'Secret показывается только один раз. Если потеряешь его, отключи и снова включи Auto Deploy для ротации.':'The secret is shown only once. If lost, disable and re-enable Auto Deploy to rotate it.'}</small></div>
 {/if}
 {:else if project.can_manage}
 {#if githubIntegrations.length}
 <div class="source-form">
  <label>{ru?'GitHub App установка':'GitHub App installation'}<select class="input" bind:value={selectedIntegration} on:change={loadGitHubRepositories}><option value="">{ru?'Выбрать установку':'Select installation'}</option>{#each githubIntegrations as integration}<option value={integration.id}>{integration.account_name}</option>{/each}</select></label>
  <label>{ru?'Репозиторий':'Repository'}<select class="input" bind:value={selectedRepository}><option value="">{ru?'Выбрать репозиторий':'Select repository'}</option>{#each githubRepositories as repo}<option value={repo.full_name}>{repo.full_name} · {repo.private?(ru?'Приватный':'Private'):(ru?'Публичный':'Public')}</option>{/each}</select></label>
  <label>{ru?'Ветка деплоя (пусто — default branch)':'Deploy branch (empty uses default branch)'}<input class="input" bind:value={selectedBranch} maxlength="255" placeholder="main"/></label>
  <div class="source-actions"><Button size="sm" on:click={loadGitHubRepositories} disabled={!selectedIntegration||sourceBusy}>{ru?'Обновить список':'Refresh repositories'}</Button><Button size="sm" variant="primary" on:click={connectRepository} disabled={!selectedRepository||sourceBusy}>{sourceBusy?(ru?'Проверка…':'Verifying…'):(ru?'Подключить репозиторий':'Connect repository')}</Button></div>
 </div>
 {:else}
 <div class="source-empty"><span class="resource-icon">GH</span><div><strong>{ru?'GitHub App не подключено':'GitHub App is not connected'}</strong><small>{ru?'Сначала подключи GitHub App, чтобы импортировать репозиторий.':'Connect the GitHub App before importing a repository.'}</small><a href="/settings/integrations/github">{ru?'Открыть GitHub App':'Open GitHub App'} →</a></div></div>
 {/if}
 {:else}
 <div class="source-empty"><span class="resource-icon">GH</span><div><strong>{ru?'Репозиторий не подключён':'No repository linked'}</strong><small>{ru?'У тебя нет прав на изменение исходного репозитория проекта.':'You do not have permission to change this project source.'}</small></div></div>
 {/if}
 {#if sourceError}<div class="source-error">{sourceError}</div>{/if}
</section>{/if}{/if}
